// Package definition contains shared types used across the provider definition.
//
// +k8s:openapi-gen=true
package definition

// Parameters are the Instance-wide parameters (Instance.spec.parameters).
type Parameters struct {
	// TLS configures the certificate clients connect to.
	// +optional
	TLS *TLSParameters `json:"tls,omitempty"`
}

// TLSParameters selects where the HTTP (client-facing) certificate comes
// from: a Secret, a cert-manager issuer, or else a CA the operator creates
// for the instance. Certificates between the nodes are always generated by
// the operator. Both fields can only be set when the instance is created.
type TLSParameters struct {
	// CertificateSecretName names a Secret in the instance namespace with
	// the HTTP certificate: tls.crt, tls.key and ca.crt. Its subject
	// alternative names must cover the instance's client Service.
	// +optional
	CertificateSecretName string `json:"certificateSecretName,omitempty"`

	// Issuer is the cert-manager issuer that signs the HTTP certificate.
	// +optional
	Issuer *IssuerReference `json:"issuer,omitempty"`
}

// IssuerKind is the kind of a cert-manager issuer.
// +enum
type IssuerKind string

const (
	// IssuerKindIssuer is an Issuer in the instance namespace.
	IssuerKindIssuer IssuerKind = "Issuer"
	// IssuerKindClusterIssuer is a cluster-wide ClusterIssuer.
	IssuerKindClusterIssuer IssuerKind = "ClusterIssuer"
)

// IssuerReference refers to a cert-manager issuer.
type IssuerReference struct {
	// Name of the issuer.
	// +optional
	Name string `json:"name,omitempty"`

	// Kind of the issuer.
	// +default="Issuer"
	// +optional
	Kind IssuerKind `json:"kind,omitempty"`
}
